{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    # Initialize allocations with minima
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum(alloc)
    # Validate budget bounds (optional, but assume valid per spec)
    if remaining < 0:
        raise ValueError('Budget below sum of minima')
    if budget > sum(seg['capacity'] for seg in segments):
        raise ValueError('Budget exceeds total capacity')
    # Distribute remaining tokens
    while remaining > 0:
        best_idx = 0
        best_val = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                # metric = importance / (next allocated position)
                metric = seg['importance'] / (alloc[i] + 1)
                if metric > best_val or (metric == best_val and i < best_idx):
                    best_val = metric
                    best_idx = i
        alloc[best_idx] += 1
        remaining -= 1
    # Build by_name mapping
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    # Total is budget (must match sum(alloc))
    total = budget
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
